import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import { updateAlbum, albumShareUrl } from '@/utils/upload/albums';
export default {
  props: {
    albums: {
      type: Array,
      default: () => []
    },
    files: {
      type: Array,
      default: () => []
    }
  },
  emits: ['updated'],
  data: () => ({
    busy: null
  }),
  methods: {
    canShare(album) {
      return album.enabled && !album.adminDisabled && (album.expiresAt == null || album.expiresAt > Date.now());
    },
    shareUrl(album) {
      return albumShareUrl(album);
    },
    progress(id) {
      const files = this.files.filter(file => file.album?.id === id);
      return {
        total: files.length,
        success: files.filter(f => ['done', 'success'].includes(f.status)).length,
        failed: files.filter(f => f.status === 'exception').length
      };
    },
    async copy(album) {
      try {
        await navigator.clipboard.writeText(this.shareUrl(album));
        this.$message.success(this.$t('albums.copied'));
      } catch {
        this.$message.error(this.$t('albums.copyFailed'));
      }
    },
    async change(album, changes) {
      this.busy = album.id;
      try {
        this.$emit('updated', await updateAlbum(album, changes));
      } catch {
        this.$message.error(this.$t('albums.actionFailed'));
      } finally {
        this.busy = null;
      }
    },
    async rename(album) {
      try {
        const {
          value
        } = await this.$prompt(this.$t('albums.name'), this.$t('albums.rename'), {
          inputValue: album.name,
          inputValidator: value => !!value?.trim() && value.trim().length <= 120
        });
        await this.change(album, {
          name: value
        });
      } catch {/* Dialog cancelled. */}
    },
    async rotate(album) {
      try {
        await this.$confirm(this.$t('albums.rotateConfirm'), this.$t('albums.rotate'));
        await this.change(album, {
          rotate: true
        });
      } catch {/* Dialog cancelled. */}
    }
  }
};